// Combine all competitor data sources and detect changes
const items = $input.all();
const competitorEvents = [];

for (const item of items) {
  try {
    const data = item.json;
    const competitorId = data.competitor_id || 'unknown';
    const competitorName = data.competitor_name || 'Unknown';

    // Extract events from press release RSS
    if (data.press_release_feed) {
      const feedContent = data.press_release_feed;
      const itemMatches = feedContent.matchAll(/<item>([\s\S]*?)<\/item>/g);

      for (const match of itemMatches) {
        const itemXml = match[1];
        const titleMatch = itemXml.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/);
        const linkMatch = itemXml.match(/<link>([\s\S]*?)<\/link>/);
        const descMatch = itemXml.match(/<description>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/);
        const pubMatch = itemXml.match(/<pubDate>([\s\S]*?)<\/pubDate>/);

        const title = titleMatch ? titleMatch[1].trim() : '';
        const url = linkMatch ? linkMatch[1].trim() : '';
        const description = descMatch ? descMatch[1].replace(/<[^>]+>/g, '').trim().substring(0, 500) : '';
        const pubDate = pubMatch ? pubMatch[1].trim() : new Date().toISOString();

        // Detect event type based on keywords
        let eventType = 'general_news';
        const titleLower = title.toLowerCase();
        const descLower = description.toLowerCase();

        if (titleLower.includes('acqui') || descLower.includes('acqui')) eventType = 'acquisition';
        else if (titleLower.includes('partner') || descLower.includes('partner')) eventType = 'partnership';
        else if (titleLower.includes('launch') || titleLower.includes('product') || titleLower.includes('release')) eventType = 'product_launch';
        else if (titleLower.includes('funding') || titleLower.includes('investment') || titleLower.includes('series')) eventType = 'funding';
        else if (titleLower.includes('ceo') || titleLower.includes('appoint') || titleLower.includes('executive')) eventType = 'leadership_change';
        else if (titleLower.includes('earnings') || titleLower.includes('revenue') || titleLower.includes('financial')) eventType = 'financial_results';

        if (title && url) {
          competitorEvents.push({
            json: {
              competitor_id: competitorId,
              competitor_name: competitorName,
              event_type: eventType,
              title,
              description,
              source_url: url,
              source_type: 'press_release',
              published_at: pubDate,
              detected_at: new Date().toISOString(),
              severity: eventType === 'acquisition' || eventType === 'funding' ? 'high' : 'medium'
            }
          });
        }
      }
    }

    // Extract from Google News results
    if (data.google_news_feed) {
      const feedContent = data.google_news_feed;
      const itemMatches = feedContent.matchAll(/<item>([\s\S]*?)<\/item>/g);
      let newsCount = 0;

      for (const match of itemMatches) {
        if (newsCount >= 5) break; // Limit to top 5 news items
        const itemXml = match[1];
        const titleMatch = itemXml.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/);
        const linkMatch = itemXml.match(/<link>([\s\S]*?)<\/link>/);
        const pubMatch = itemXml.match(/<pubDate>([\s\S]*?)<\/pubDate>/);

        const title = titleMatch ? titleMatch[1].trim() : '';
        const url = linkMatch ? linkMatch[1].trim() : '';
        const pubDate = pubMatch ? pubMatch[1].trim() : new Date().toISOString();

        if (title && url) {
          competitorEvents.push({
            json: {
              competitor_id: competitorId,
              competitor_name: competitorName,
              event_type: 'media_mention',
              title,
              description: '',
              source_url: url,
              source_type: 'google_news',
              published_at: pubDate,
              detected_at: new Date().toISOString(),
              severity: 'low'
            }
          });
          newsCount++;
        }
      }
    }
  } catch (err) {
    console.log(`Error extracting competitor events: ${err.message}`);
  }
}

return competitorEvents.length > 0 
  ? competitorEvents 
  : [{ json: { status: 'no_events', count: 0 } }];

// Check if there are high-severity events to trigger intel report
const items = $input.all();
const highSeverityEvents = items.filter(item => 
  item.json.severity === 'high' || item.json.severity === 'critical'
);

if (highSeverityEvents.length === 0) {
  return [{ json: { status: 'no_critical_events', generate_report: false } }];
}

return [{
  json: {
    generate_report: true,
    event_count: highSeverityEvents.length,
    events: highSeverityEvents.map(e => e.json),
    report_trigger: 'high_severity_competitor_events',
    triggered_at: new Date().toISOString()
  }
}];
